def main():
    ids = sys.argv[1:]
    out = []
    for cid in ids:
        rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
               "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
        path = os.path.join(BASE, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        # self-verify
        with open(path, encoding="utf-8") as f:
            chk = json.load(f)
        assert set(chk.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert set(chk["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
        assert isinstance(chk["confidence"], (int,float)) and 0 <= chk["confidence"] <= 1, cid
        out.append((cid, path, os.path.getsize(path)))
    for cid, path, size in out:
        print(cid, size, path)
    print("WROTE", len(out))

if __name__ == "__main__":
    main()
